import { z } from "zod";

import { LIMITS, parseDecimal } from "@/lib/calculator";
import { SLUG_SHAPE } from "@/lib/route-gate";

/*
 * The test shop cart, shared by the browser and the server (see docs/ARCHITECTURE.md). A line is a product slug and an AREA in m2 hundredths
 * (integer, 0.01 - 10 000 m2, the calculator's limits). The browser keeps the cart in localStorage; the server
 * never trusts it: prices, availability and totals always come from `quoteCart` / `placeTestOrder`.
 */

export const CART_STORAGE_KEY = "stone.cart.v1";
export const CART_MAX_LINES = 20;
export const AREA_MIN_HUNDREDTHS = Math.round(LIMITS.area[0] * 100);
export const AREA_MAX_HUNDREDTHS = Math.round(LIMITS.area[1] * 100);
/** At most this many test checkout orders per user (checked inside the insert statement). */
export const TEST_ORDER_CAP = 50;
/** Line and order totals are stored as Postgres `integer` cents. */
export const MAX_CENTS = 2_147_483_647;

export type CartLine = { slug: string; areaHundredths: number };

export const cartLine = z
  .object({
    slug: z.string().max(100).regex(SLUG_SHAPE),
    areaHundredths: z
      .number()
      .int()
      .min(AREA_MIN_HUNDREDTHS)
      .max(AREA_MAX_HUNDREDTHS),
  })
  .strict();

export const cartItems = z.array(cartLine).max(CART_MAX_LINES);

/** The calculator's rounding: round(area hundredths x price per m2 in cents / 100), half up. */
export function lineTotalCents(areaHundredths: number, priceCents: number) {
  return Math.round((areaHundredths * priceCents) / 100);
}

/** Half-up to hundredths without binary drift (the calculator's rule). */
function toHundredths(value: number): number {
  return Math.round(Number(`${Number(value.toPrecision(12))}e2`));
}

/** "2,2" / "2.2" / "10 000" -> hundredths, with the calculator's parse and its 0.01 - 10 000 m2 range. */
export function parseArea(
  raw: string,
):
  | { ok: true; hundredths: number }
  | { ok: false; reason: "invalid" | "range" } {
  const value = parseDecimal(raw);
  if (value === null) return { ok: false, reason: "invalid" };
  const hundredths = toHundredths(value);
  if (hundredths < AREA_MIN_HUNDREDTHS || hundredths > AREA_MAX_HUNDREDTHS)
    return { ok: false, reason: "range" };
  return { ok: true, hundredths };
}

const capped = (h: number) => Math.min(h, AREA_MAX_HUNDREDTHS);

/** Duplicates merged by slug (first position kept), areas added and capped at 10 000 m2. */
export function mergeLines(lines: readonly CartLine[]): CartLine[] {
  const merged: CartLine[] = [];
  for (const line of lines) {
    const existing = merged.find((l) => l.slug === line.slug);
    if (existing)
      existing.areaHundredths = capped(
        existing.areaHundredths + line.areaHundredths,
      );
    else merged.push({ slug: line.slug, areaHundredths: line.areaHundredths });
  }
  return merged;
}

/** Adding a product that is already in the cart adds its area. */
export function addLine(lines: readonly CartLine[], line: CartLine) {
  return mergeLines([...lines, line]);
}

/** A stored cart, keeping only valid lines (a tampered or old entry never breaks the page). */
export function parseStoredCart(raw: string | null): CartLine[] {
  if (!raw) return [];
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return [];
  }
  if (!Array.isArray(value)) return [];
  const valid = value.flatMap((entry) => {
    const parsed = cartLine.safeParse(entry);
    return parsed.success ? [parsed.data] : [];
  });
  return mergeLines(valid).slice(0, CART_MAX_LINES);
}

export type QuoteLine =
  | {
      slug: string;
      areaHundredths: number;
      available: true;
      /** Stored translation for the locale, or null (the client falls back to messages, then the slug). */
      name: string | null;
      material: string;
      finish: string;
      image: string;
      imageFit: "cover" | "contain";
      priceCents: number;
      isPlaceholder: boolean;
      lineTotalCents: number;
    }
  | { slug: string; areaHundredths: number; available: false };

export type Quote = {
  lines: QuoteLine[];
  /** Sum of the available lines. */
  totalCents: number;
  /** The total is above what an order can store (`MAX_CENTS`); such a cart cannot be ordered. */
  tooLarge: boolean;
  /** Not empty, every line available and not too large. */
  orderable: boolean;
};

export type QuoteResult =
  { ok: true; quote: Quote } | { ok: false; code: "invalid" | "generic" };

export type PlaceOrderCode =
  | "unavailable"
  | "invalid"
  | "empty"
  | "product_unavailable"
  | "too_large"
  | "limit"
  | "conflict"
  | "generic";

export type PlaceOrderResult =
  | { ok: true; number: string }
  | { ok: false; code: "prices_changed"; quote: Quote }
  | { ok: false; code: PlaceOrderCode };

"use server";

import { createHash } from "node:crypto";
import { revalidatePath } from "next/cache";
import { z } from "zod";

import {
  cartItems,
  MAX_CENTS,
  mergeLines,
  TEST_ORDER_CAP,
  type CartLine,
  type PlaceOrderResult,
  type QuoteResult,
} from "@/features/cart/input";
import { requireUser } from "@/server/auth/guards";
import { requestLocale } from "@/server/auth/request-locale";

import { getDb } from "../db";
import { sameOrigin } from "../same-origin";
import { buildQuote } from "./quote";
import { countTestOrders, findTestOrder, insertTestOrder } from "./store";

/*
 * Test shop checkout (docs/ARCHITECTURE.md). No payment is taken
 * and nothing is delivered: an order is a record the customer and the admin can follow.
 */

function parseCart(items: unknown): CartLine[] | null {
  const parsed = cartItems.safeParse(items);
  return parsed.success ? mergeLines(parsed.data) : null;
}

/**
 * Public and read-only by design: prices the visitor's cart (a Guest builds a cart too). It takes only slugs and
 * areas, never a user id, reads only published catalog data and writes nothing.
 */
export async function quoteCart(
  items: unknown,
  locale: unknown,
): Promise<QuoteResult> {
  const lines = parseCart(items);
  if (!lines || lines.length === 0) return { ok: false, code: "invalid" };
  try {
    return {
      ok: true,
      quote: await buildQuote(lines, locale === "en" ? "en" : "ru"),
    };
  } catch {
    return { ok: false, code: "generic" };
  }
}

const orderInput = z
  .object({
    items: z.unknown(),
    key: z.uuid(),
    expectedTotalCents: z.number().int().min(0).max(MAX_CENTS),
  })
  .strict();

function digestOf(lines: readonly CartLine[]) {
  return createHash("sha256").update(JSON.stringify(lines)).digest("hex");
}

/**
 * Places a test order for the signed-in user. The server re-prices the cart; when its total differs from the one
 * the customer confirmed it answers `prices_changed` with the fresh quote and orders nothing. A retry with the same
 * key returns the same order (or `conflict` when the content differs).
 */
export async function placeTestOrder(
  input: unknown,
): Promise<PlaceOrderResult> {
  const user = await requireUser(await requestLocale());
  if (!(await sameOrigin())) return { ok: false, code: "invalid" };
  const parsed = orderInput.safeParse(input);
  if (!parsed.success) return { ok: false, code: "invalid" };
  const lines = parseCart(parsed.data.items);
  if (!lines) return { ok: false, code: "invalid" };
  if (lines.length === 0) return { ok: false, code: "empty" };
  const { key, expectedTotalCents } = parsed.data;
  const digest = digestOf(lines);
  const settle = (found: { number: string; digest: string | null }) =>
    found.digest === digest
      ? ({ ok: true, number: found.number } as const)
      : ({ ok: false, code: "conflict" } as const);
  try {
    const db = await getDb();
    if (!db) return { ok: false, code: "unavailable" };
    const existing = await findTestOrder(db, user.id, key);
    if (existing) return settle(existing);

    const locale = await requestLocale();
    const quote = await buildQuote(lines, locale);
    if (quote.tooLarge) return { ok: false, code: "too_large" };
    if (!quote.orderable) return { ok: false, code: "product_unavailable" };
    if (quote.totalCents !== expectedTotalCents)
      return { ok: false, code: "prices_changed", quote };
    if ((await countTestOrders(db, user.id)) >= TEST_ORDER_CAP)
      return { ok: false, code: "limit" };

    let number: string | null;
    try {
      number = await insertTestOrder(
        db,
        user.id,
        key,
        digest,
        lines,
        expectedTotalCents,
      );
    } catch {
      number = null;
    }
    if (number) {
      revalidatePath("/[locale]/account", "layout");
      revalidatePath("/[locale]/admin", "layout");
      return { ok: true, number };
    }
    // Nothing inserted: a concurrent attempt with this key won, or something changed between the quote and the insert.
    const won = await findTestOrder(db, user.id, key);
    if (won) return settle(won);
    if ((await countTestOrders(db, user.id)) >= TEST_ORDER_CAP)
      return { ok: false, code: "limit" };
    const fresh = await buildQuote(lines, locale);
    if (fresh.tooLarge) return { ok: false, code: "too_large" };
    if (!fresh.orderable) return { ok: false, code: "product_unavailable" };
    if (fresh.totalCents !== expectedTotalCents)
      return { ok: false, code: "prices_changed", quote: fresh };
    return { ok: false, code: "generic" };
  } catch {
    return { ok: false, code: "unavailable" };
  }
}

import AxeBuilder from "@axe-core/playwright";
import { expect, test, type Page } from "@playwright/test";

import en from "../../messages/en.json";
import ru from "../../messages/ru.json";

/*
 * Site shell e2e (Phase 3, Task 4). Runs in the `desktop` (1440) and `mobile` (390) projects.
 * The shell lives in `src/app/[locale]/(site)/layout.tsx`: header, `<main>`, footer, tab bar.
 */

const MESSAGES = { ru, en } as const;
const LOCALES = ["ru", "en"] as const;

/** Resolves once React attached its props to the language switch (hydration reached the island). */
async function hydrated(page: Page) {
  await page.waitForFunction(() => {
    const button = document.querySelector<HTMLElement>(
      "header button[aria-label^='RU / EN'], [role=dialog] button[aria-label^='RU / EN']",
    );
    const probe =
      button ??
      document.querySelector<HTMLElement>("header button[aria-haspopup]");
    if (!probe) return false;
    const key = Object.keys(probe).find((k) => k.startsWith("__reactProps$"));
    return key !== undefined;
  });
}

test.describe("site shell", () => {
  test("shell renders header, footer and tab bar at 390", async ({
    page,
  }, testInfo) => {
    test.skip(testInfo.project.name !== "mobile", "phone layout only");
    const response = await page.goto("/ru");
    expect(response?.status()).toBe(200);

    await expect(page.getByRole("banner")).toBeVisible();
    await expect(page.getByRole("contentinfo")).toBeVisible();
